// Initial file generated by Claude Sonnet 5.5

import { describe, expect, it } from "vitest";

import { sanitizeHTML } from "@/core/sanitizeHTML.ts";

describe("sanitizeHTML", () => {

  it("keeps allowed formatting and safe links", () => {
    const out = sanitizeHTML("<p>Hi <b>there</b> <a href=\"https://example.com\">link</a></p>");
    expect(out).toContain("<b>there</b>");
    expect(out).toContain("href=\"https://example.com\"");
  });

  it("removes `<script>` elements", () => {
    expect(sanitizeHTML("<p>ok</p><script>alert(1)</script>")).not.toMatch(/script/i);
  });

  it("removes inline event handlers", () => {
    const out = sanitizeHTML("<img src=\"x\" onerror=\"alert(1)\">");
    expect(out).not.toMatch(/onerror/i);
  });

  it("neutralizes `javascript:` URLs", () => {
    const out = sanitizeHTML("<a href=\"javascript:alert(1)\">click</a>");
    expect(out).not.toMatch(/javascript:/i);
  });

  it("drops tags that are not on the allow-list (iframe, form, svg)", () => {
    const out = sanitizeHTML("<iframe src=\"https://evil.example\"></iframe><form><input></form><svg onload=\"x()\"></svg>");
    expect(out).not.toMatch(/<iframe|<form|<input|<svg/i);
  });

  it("returns an empty string for empty input", () => {
    expect(sanitizeHTML("")).toBe("");
  });

});
